import { readFileSync } from "node:fs";

// The catalog builder renders these fields as text. Source URLs are rendered separately.
const pages = new Map();
function add(key, headline, intro, sections, faq, demoTitle, demoText) {
  pages.set(key, {headline, intro,
    sections: sections.map(([title,text]) => ({title,text})),
    faq: faq.map(([question,answer]) => ({question,answer})),
    demo:{title:demoTitle,text:demoText}});
}

add("products/lotline","Merchandise the car that’s on the lot",
  "Two vehicles can share a year, make and model and still be very different purchases. The listing is the place to explain which one has the tow package, which one is waiting on photos and which price applies to the unit in front of the shopper.",
  [["At intake","Paste the VIN, compare the decoded identity with the vehicle, and fill the gaps from the car or its documentation. A salesperson can add a stock number that is easier for a customer to say over the phone."],
   ["On the vehicle page","Lead the gallery with an actual exterior view. Follow it with seating, controls, cargo space and the pieces of equipment someone shopping that model usually asks about. Place the cash price and available payment options on the same listing."],
   ["When the car leaves","Mark the unit sold in inventory and review the public shopping experience. Staff can keep the shopper’s original question in the lead record for a conversation about a suitable replacement."]],
  [["Does decoding the VIN fill in every option?","Available fields depend on manufacturer data. Review trim, packages and factory equipment against the specific unit. Add mileage, condition, photos and the dealer’s price yourself."],
   ["Can I use our building as the homepage image?","Yes. Upload a dealership photo for the hero and use actual vehicle galleries on individual listings. A store can also run promotional banners on the homepage."]],
  "Try two similar vehicles","Open two listings for the same model. Compare the galleries, equipment and price, then ask about one by stock number and check that the inquiry follows that unit.");

add("products/local-reach","Help a local shopper find the right door",
  "Someone searching for the parts counter on Saturday has different needs from someone looking for an SUV. Give each person a page with a useful destination, a working phone number and information that agrees with the store.",
  [["Choose the destination","Send a model shopper to available inventory, a service customer to the service page and a parts buyer to the correct department. A general homepage can hide the answer for all three."],
   ["Check the visible facts","Compare the published sales, parts and service hours with the schedules staff actually work. Review the public address, phone links and department pages after moving a counter or changing weekend coverage."],
   ["Plan a domain move","List the old URLs that receive traffic and choose their destinations before DNS changes. Check published pages, canonical URLs and the sitemap on the connected domain; measure rankings in the store’s own reporting tools."]],
  [["Does this manage my Google Business Profile?","Rooftop settings publish information on the dealership’s own site. Profile edits, directory distribution and account access need their own workflow."],
   ["What should we bring to a migration review?","Bring the current domain, department URLs, the most visited inventory or service pages and the person who controls DNS."]],
  "Audit one Saturday search","Use a phone to find Saturday parts hours, tap the displayed phone number and compare the route with the contact information your parts manager uses.");

add("products/answer-index","Make each answer traceable to a dealership fact",
  "Answer Index is planned for stores that want to understand how AI search systems describe them. Start with the questions a real customer would ask in the market, then identify what page and evidence could support a correct answer.",
  [["Choose repeatable questions","Write down the market, question and intended meaning. “Where can I test drive a used pickup Saturday?” tests different information from a question about which trucks have a particular package."],
   ["Capture the evidence","The proposed report keeps the date, answer, cited page and the dealership fact that was correct that day. A reply citing an old inventory page needs a different fix from a current page showing an incorrect closing time."],
   ["Review the next change","A human reviewer can decide whether a source page needs clearer language, fresher inventory or a correction to an offer. Repeat the same question set after correcting the underlying facts."]],
  [["Can a dealership guarantee it appears in an AI answer?","Search providers decide what they surface. A repeatable sample can show where an answer appeared, what it cited and how that changed."],
   ["Can I buy an automated visibility report today?","Answer Index is on the roadmap. A discovery session can establish the questions, source pages and evidence your team would want in a pilot."]],
  "Bring three local questions","Choose a stock question, a department question and a payment question. We can map each one to a source a human could verify.");

add("products/deal-path","Give the next call a concrete starting price",
  "A shopper may know how much cash they have today and what fits their pay cycle. Give them a useful comparison on the vehicle page, then let the dealership handle the personal credit and contract details.",
  [["Choose the pricing mode","Set the store’s financing policy, then check the individual unit. A cash-only vehicle can carry its selling price. An eligible in-house unit can show its own cash price, financing price, down payment and schedule."],
   ["Read the entire schedule","Compare the cash due, payment frequency and term together. A biweekly buyer pays every two weeks. Have a salesperson review the calculated balance and final installment against the terms the dealer intends to publish."],
   ["Carry questions to the sales desk","A shopper can ask about a trade, request an appointment or clarify a particular payment. Staff can use the selected stock number to continue from the same published terms."]],
  [["Can a store hide APR estimates and still show BHPH?","Yes. Configure the dealership for in-house financing and review the individual vehicle’s pricing mode and published schedule."],
   ["Does the displayed payment approve the shopper for financing?","The page presents the dealer’s published terms or an illustrative estimate. The dealership handles eligibility, underwriting and contract execution."]],
  "Compare a cash sale with an in-house sale","Bring one cash-only unit and one financed unit. Read each pricing panel aloud as a shopper would and check the down payment, term and frequency with your finance manager.");

add("products/offer-board","Give every promotion an owner and an end date",
  "The person who supplies the artwork, the person who changes the homepage and the person who answers the resulting calls may work in different departments. A useful banner tells all three exactly what the shopper saw.",
  [["Build around one action","Decide whether the creative points to eligible inventory, a service offer or a specific vehicle. Open that destination on a phone and compare the terms there with the words on the image."],
   ["Preserve the reviewed version","For a franchise preview, pair the approved artwork revision with its disclosure and effective dates. A replacement image changes what the shopper sees and should receive its own review."],
   ["Inspect the last day","Review the start and end of the offer, including the time zone. Check what the homepage and destination show when eligibility ends or the featured unit sells."]],
  [["Can a dealer run a rotating homepage promotion?","Yes. Homepage banners and slides are managed in the dealer workspace. Use images that remain legible on a phone and link each slide to the relevant destination."],
   ["Does an internal approval authorize OEM reimbursement?","A staff approval records an internal review. Reimbursement eligibility and manufacturer approval come from the applicable program."]],
  "Review a weekend special","Bring the actual image, disclosure and destination for one promotion. Walk through the desktop crop, phone crop and the experience after the offer ends.");

add("products/shopper-paths","Design the next step around a stated need",
  "Shopper Paths is planned personalization for dealer websites. A customer who explicitly chooses space for three children has given the store a useful starting point. A customer who asks about weekly cash flow has given it a different one.",
  [["Name the signal","Use a choice the shopper understands, such as seating, towing needs or a payment frequency. Document what the shopper selected and why the next suggestion would help them."],
   ["Define a useful branch","A seating path could lead to listings with verified third-row equipment. A budget path could lead to published in-house schedules. Plan a fallback when the store has no matching inventory."],
   ["Agree on the outcome","Evaluate whether shoppers find a suitable unit, ask an informed question or book a visit. The proposed pilot should compare outcomes alongside the effect of changing inventory."]],
  [["Is personalization available across every shopper journey today?","Shopper Paths is planned. The existing showroom already offers inventory filters, listing pages and stock-specific inquiries a salesperson can demonstrate."],
   ["How would my team control a recommendation?","The pilot design begins with a dealer-approved audience, content, destination and rule for withdrawing a recommendation."]],
  "Map a real shopping decision","Bring three common phrases your salespeople hear. For each, identify an inventory field, a helpful destination and what staff should say when there are no matches.");

add("products/rooftop-profile","Publish the details your receptionist gives callers",
  "A listing can bring a shopper to the right vehicle and still send them to the wrong entrance. Keep the information a visitor needs at the store level, especially when sales and service open at different times.",
  [["Start at the curb","Check the street address from the visitor’s point of view. Give them the right sales number and a separate parts or service line when those departments answer independently."],
   ["Publish departmental hours","Enter a weekly schedule for the departments the store wants to display. Walk through a day when the showroom is open and service is closed to confirm the distinction is clear."],
   ["Check each rooftop separately","Multi-location teams should open the public site for each location after an edit. Verify the logo, department details and local links against that specific store."]],
  [["Can staff update our logos for both background colors?","Yes. Store settings support separate light- and dark-background logo assets. Preview each in the published theme."],
   ["Will changing these hours edit third-party directories?","The current profile controls your own site. External directory sync is planned and would require the relevant account permissions."]],
  "Find a counter from a phone","Ask someone unfamiliar with the store to locate Saturday service hours and call the service line. Use their experience to identify the fields to correct.");

add("products/stock-inbox","Answer the question that made the shopper reach out",
  "“Is it still available?” and “Will my rear-facing seat fit behind the driver?” can come from shoppers viewing the same car. Staff need the wording, contact details and stock number to give each one a useful reply.",
  [["Read the inquiry in context","Open the private inquiry and compare the cited stock number with the vehicle page. Check current availability before promising a visit or describing equipment that could differ between trims."],
   ["Give the next action an owner","A salesperson can claim the inquiry or a manager can assign it. Add the next task, due time and a note about what needs checking. Staff can revisit work that is due and record completion."],
   ["Keep the original intent","If a shopper mentions a trade, a seating need or a specific photo, preserve that detail where the next salesperson can find it. A scheduled visit has its own appointment record."]],
  [["Can a shopper submit a question by voice?","The website concierge can collect a name, callback number, stock number and question and submit them to the store’s inquiry flow."],
   ["Can an inquiry be handled without an external CRM?","Yes. Staff can work in the dealership’s private workspace. A dealership requiring an outside CRM connection should specify the provider and delivery fields during discovery."]],
  "Try the same car through two channels","Send a typed question and a voice question with different wording about the same stock number. Have sales locate both and decide who should follow up.");

add("products/visit-count","Measure appointments a salesperson can actually find",
  "The useful point to count is when the dealership has a confirmed appointment. A shopper may open the form twice, ask the concierge to repeat the time or refresh the page while waiting for a response.",
  [["Keep the booking receipt","The booking record carries its confirmation identity and vehicle context. Use it to reconcile a recorded conversion with an appointment staff can open."],
   ["Follow the changes","When a shopper calls to move Saturday’s visit to Monday, reschedule the existing appointment. Keep the outcome of that visit distinct from the date of the original request."],
   ["Choose the denominator","Use appointments due during a period to discuss attendance. Use qualified inquiries received during a period to discuss booking. A long sales cycle can place those events in different weeks."]],
  [["What happens if the booking is submitted again?","The booking workflow protects repeated submissions for the same confirmed request. Reconcile counts against confirmation identities when reviewing conversions."],
   ["Can we report vehicle sales from attendance alone?","Attendance records show who came in. Confirming a sale requires a matched dealership outcome. Cross-channel revenue attribution is a separate reporting project."]],
  "Reconcile a changed appointment","Book a sample visit, move it to another time and inspect the staff record. Identify which date belongs in a booking report and which belongs in an attendance report.");

add("products/contact-permissions","Know what the shopper agreed to receive",
  "A buyer who asks for a photo by email has made a specific request. A useful permission record preserves what the buyer asked for and helps staff decide how a later conversation should continue. The cross-channel permissions workspace is planned.",
  [["Capture the context","The proposed record ties the dealership, contact channel, purpose and wording to the time of the shopper’s choice. That detail matters when different stores in a group serve the same household."],
   ["Check before dispatch","A queued follow-up can outlive the shopper’s permission. The planned workflow rechecks the latest choice before sending and routes an interrupted conversation back to staff."],
   ["Review a handoff","Have the receptionist and sales manager walk through a one-time reply, an appointment reminder and a promotion. Identify who handles declines and what evidence each person can see."]],
  [["Will connecting an email or texting provider activate promotions?","A provider connection supplies transport. Campaign activation, audience selection and permission for the intended use are separate setup decisions."],
   ["Can I use this page as legal approval for a campaign?","Your dealership’s adviser and messaging provider can review the actual audience, copy and permissions. This page describes a planned dealership workflow."]],
  "Run a withdrawal exercise","Start with a shopper who requested an availability reply and later withdrew permission. Decide which planned messages should stop and which employee owns the remaining inquiry.");

add("products/access-review","Test whether a shopper can finish the task",
  "The proposed Access Review service follows a real shopping task through every step. A readable homepage is only the beginning when the shopper must open filters, inspect a listing, fix an error and confirm a visit.",
  [["Choose a complete journey","Start on a phone or with a keyboard. Find a vehicle, open the gallery, enter a question and submit it. Record the first step where the shopper loses focus or cannot understand what to do next."],
   ["Exercise error conditions","Leave a required field empty, propose an unavailable slot and reopen a dialog. The shopper should be able to find the error, correct it and identify the successful result."],
   ["Retest the same task","Document the device, browser, page, input method and observed behavior. After the fix, repeat that exact journey and include it when the store changes themes or forms."]],
  [["Is a formal accessibility audit included in every website plan?","Access Review is planned. Discuss the proposed scope, testing methods and evidence your procurement team requires before purchasing an audit."],
   ["Why check a second theme?","A background or accent change can affect text, focus indicators, labels and error messages. Review representative pages in the actual theme the store publishes."]],
  "Try a keyboard-only test drive request","Open the inventory, select a listing, fill the form and return to the original page using the keyboard. Keep a note of anything that requires guessing.");

add("products/lot-guide","Let the shopper name the car and keep browsing",
  "Someone comparing two similar trucks may remember the stock number more clearly than the trim. Lot Guide can start with that number, stay with a shopper as they open a listing and help turn the conversation into a question or a visit.",
  [["Establish the vehicle","Ask about the current listing or say a stock number. If there is ambiguity, identify the year, make and model before acting. A shopper should hear the car they meant before an appointment is offered."],
   ["Move from browsing to booking","Use a time offered by the dealership, collect the required contact information and confirm the booking details. Staff should see a confirmed appointment before the shopper is told the visit is booked."],
   ["Give sales a reason to prepare","Ask whether the shopper has a trade or anything specific to see. A note such as “please open the third row before we arrive” tells a salesperson exactly how to prepare the car."]],
  [["Can the shopper hide the widget while talking?","The hosted showroom allows the voice conversation to continue while the shopper closes the on-screen panel and browses supported vehicle pages."],
   ["What happens if the listing does not confirm an option?","The assistant can collect the shopper’s question and contact information for staff to verify the unit. A salesperson can answer from the car or its documentation."]],
  "Use a stock number in your demo","Open a listing, start voice and ask about that stock number. Minimize the panel, browse the vehicle page and then request an available test-drive time.");

add("products/front-desk","Design the call around the person who should answer",
  "A sales call about a trade, a parts request and a service customer collecting a vehicle should have different destinations. Before enabling phone coverage, map those destinations against the way your store handles calls today.",
  [["Draw the call path","List the main number, forwarding method, hours and the extension or line for each department. Include what should happen when a department is closed or no employee answers."],
   ["Give the receptionist useful facts","Review the dealership’s address, hours, inventory source and instructions for appointment requests. Decisions involving credit, an appraisal or a repair order belong with the dealership employee authorized to handle them."],
   ["Make a real test call","Use an outside phone and ask a realistic question. Check the destination, caller experience and information available to the employee receiving the call before advertising the number."]],
  [["Can I keep the current dealership website?","Yes. The phone-only package is designed for that setup. Forwarding and handoff details are confirmed during onboarding."],
   ["How do I compare voice plans?","Estimate connected call minutes and website voice use separately, then compare the included pool for your chosen plan. The pricing page lists plan allowances and overage rates."]],
  "Map a Saturday call","Bring a sales call, a parts question and an after-hours scenario. Write down where each should go and what a caller should hear if nobody can pick up.");

add("products/lot-chat","Add an inquiry desk to the website you already have",
  "A dealership can try conversational lead capture before deciding whether to migrate its website. Start with a stock question that a shopper asks often and make sure the person following up receives enough information to answer it.",
  [["Agree on what the widget can read","Identify the existing website platform and approved inventory source. Work through whether a listing provides a usable stock number or whether the shopper will need to say or type it."],
   ["Choose the placement","Test the entry point against mobile navigation, cookie controls and the site’s existing contact buttons. Staff should be able to explain how a shopper opens and closes it."],
   ["Check the receiving side","Submit a realistic question about an actual unit. Inspect the dealership, stock reference and callback details in the agreed destination and assign a person to respond."]],
  [["Will the widget take over navigation on our current site?","The shopper controls navigation on a third-party website. Guided navigation between supported pages is a feature of the hosted showroom."],
   ["Can we add phone coverage later?","Yes. Review phone-only and combined phone and widget packages on the pricing page, then plan a call-routing test with the dealership."]],
  "Try an existing vehicle page","Bring your current website address and a stock number. We can examine where a shopper opens chat and what context should appear in the staff handoff.");

add("products/copy-desk","Review a vehicle claim before a shopper relies on it",
  "A draft can sound convincing while quietly assigning the wrong equipment to a trim. Copy Desk is a planned editorial workflow for the person who must verify a claim before putting the dealership’s name on it.",
  [["Gather the source material","Start with the dealer’s listing, available factory documentation and the approved offer text. Mark a field as unresolved when those sources disagree or when data belongs to a different model year."],
   ["Review high-impact sentences","Send equipment, manufacturer claims, eligibility language and financial terms to the appropriate employee. The proposed workflow keeps the exact revision and the evidence the reviewer considered."],
   ["Withdraw stale content","An offer can expire while an article or campaign still points to it. Identify the pages using the reviewed copy and decide how to replace or retire it as part of the publishing decision."]],
  [["Will AI-generated copy publish automatically?","Copy Desk is planned around review of the actual draft. Brand claims and payment terms should be checked against current dealership-approved evidence before publication."],
   ["What should we use in a pilot?","Choose one inventory-based article and one offer with an expiration date. They exercise different review needs and make stale content easy to spot."]],
  "Edit a sentence with disputed equipment","Bring a factory document and an existing listing that describe the same car differently. Decide what can be published, what should be removed and who can resolve the discrepancy.");

add("products/feed-desk","Keep advertised inventory tied to the living lot",
  "A vehicle feed is most useful when its price, image and destination agree with what a shopper finds on the dealer website. Feed Desk gives staff an inventory-side check before Google processes the export.",
  [["Identify the location","Set the Google Business Profile store code for the dealership and review the required vehicle attributes. Confirm the listing points to this rooftop and shows the cash price a shopper will see on arrival."],
   ["Inspect excluded stock","Use diagnostics to identify missing information such as VIN, price, image, mileage or condition. Correct the vehicle record, then inspect the next generated feed for that stock number."],
   ["Reconcile the sold unit","Mark a test vehicle sold and confirm that its VIN leaves the next feed. The external account’s fetch schedule, review and ad delivery determine when the change appears outside the showroom."]],
  [["Does a valid feed launch an ad campaign?","The export supplies inventory data. Merchant Center eligibility, account linking, campaign setup, approval and budget are separate Google account steps."],
   ["Who should review a rejected listing?","The inventory manager can verify the vehicle fields and landing page. The Google account owner can then compare the feed with the diagnostics Google reports."]],
  "Trace one eligible VIN","Bring the store code and one listing with a price, photo, mileage and condition. Compare the website and feed, then review how a sold status changes eligibility.");

add("solutions/independent-dealers","A digital lot one person can work between walk-ins",
  "On a small lot, the person taking a trade may also photograph it, update the website and call back a shopper. Begin with the few pieces of information that make the next customer conversation easier.",
  [["Photograph today’s arrival","Add the VIN, actual mileage, asking price and stock number. Order the gallery the way you would walk someone around the car. Use the store’s photo as the homepage hero while the new listing is being prepared."],
   ["Handle the first question","Give the shopper the full listing and a way to say exactly what they need. Read the question alongside the stock number, claim the inquiry and give the callback a due time."],
   ["Close the loop at the lot","Record the scheduled visit and its outcome. If the unit sells, mark it sold so the next shopper starts with current availability. Keep notes on preferences for a suitable replacement."]],
  [["Do we need to replace our phone system at launch?","The dealership can start with the website and select voice or phone coverage according to its chosen plan. A phone rollout can be evaluated separately."],
   ["What makes a good first inventory sample?","Choose a recent arrival, a vehicle with optional equipment and a lower-priced car. Together they expose the common gaps in photos, features and payment presentation."]],
  "Run a shift change","Have one employee enter the car and another call back the sample lead. The second person should be able to locate the vehicle and understand exactly why the shopper called.");

add("solutions/buy-here-pay-here","Sell the visit with a schedule the shopper can read",
  "A customer paid every other Friday may ask about cash due today before asking about the vehicle’s trim. The store needs to show the actual schedule it offers and give its salesperson enough context to answer the next question.",
  [["Build one real offer","Use the price your store charges for cash, the BHPH price, the required cash down and the balance your staff expects to finance. Select the offered payment cadence and term, then read the full schedule before publishing."],
   ["Check exceptions by vehicle","A cash-only trade or a vehicle awaiting finance terms can have a different pricing setup. Review how each appears when conventional APR estimates are switched off site-wide."],
   ["Prepare the salesperson","Let the shopper identify a stock number and ask whether their trade or payday can work. The dealership evaluates the trade and final terms; the staff record preserves what the shopper wants to discuss."]],
  [["What if everything is already included in our price?","Start from the amount the store intends to display and check it against the calculated balance and schedule. The dealer should review any separately configured fees so it can explain the final figures."],
   ["Does this handle collections after delivery?","The showroom supports pre-sale affordability, shopper questions and appointments. Post-sale servicing, collections and payoff accounting require a servicing system."]],
  "Bring a paper payout schedule","Choose one real stock number and cover personal information. Compare the dealer’s schedule with the public cash-down amount, payment frequency, term and final installment.");

add("solutions/franchise-dealers","Run a franchise preview against the packet your store uses",
  "A franchise website decision involves more than a visual review. The website, creative, endpoint for leads and manufacturer program can each have their own approval owner. Put one representative offer through that entire chain during evaluation.",
  [["Gather the retailer materials","Ask for the current market and brand packet, authorized artwork and a contact who can confirm the permitted uses. Record the date and applicable rooftop inside the review process."],
   ["Preview the actual creative","Check phone and desktop crops, effective dates, disclosures and the landing page. Give a reviewer the exact image that will appear on the storefront and keep the decision with that revision."],
   ["Establish the launch condition","Ask the manufacturer whether this rooftop may use the proposed provider for the intended service. Website eligibility, advertising eligibility and co-op reimbursement need their own confirmation."]],
  [["Is AutoDealership.SI certified for my manufacturer?","OEM programs are Coming Soon. Current work focuses on franchise templates, reference material and review tools. Confirm provider eligibility in writing before a certified website migration."],
   ["What can we evaluate now?","The showroom, VIN-level merchandising, appointment flow, private brand library and internal offer review can be demonstrated while program eligibility is being explored."]],
  "Rehearse an expiring incentive","Bring one approved promotion with its eligibility rules, artwork, destination and end date. Ask your reviewer to identify every element that must change when it expires.");

add("solutions/dealer-groups","Give each rooftop a clear owner",
  "A group website project can look complete while leads travel to the wrong location. Establish the store identity, staff access, inventory and handoff at one rooftop before using that configuration as a model elsewhere.",
  [["Create the first preview","Choose a distinctive subdomain and the correct dealership name. Assign the engineer, identify the store administrator and review branding, department lines and the time zone."],
   ["Test separation from a second location","Use two inventory samples and two staff accounts during testing. A salesperson should be able to find their own store’s customer and vehicle while every shopper sees the correct public address and number."],
   ["Sequence the remaining sites","Decide which settings belong to the group and which each general manager owns. Record the next store’s DNS owner, training time and acceptance contact before scheduling its cutover."]],
  [["Can our engineers prepare a store before it pays?","A platform administrator or assigned engineer can prepare a client preview and its dealership configuration before the commercial activation step."],
   ["Can group leaders see all sales attributed across rooftops?","Cross-rooftop revenue attribution is on the roadmap. Define which dealership system owns sold outcomes before setting group reporting expectations."]],
  "Check a same-name model at two lots","Use different stock numbers for similar vehicles at two locations. Follow a shopper question through to the receiving store and verify the second store’s inventory stays separate.");

add("solutions/keep-your-website","Start at the contact point that needs help",
  "If the current site is under contract or already performs well, a dealership can evaluate inbound phone and chat without moving its inventory pages or changing DNS. The first decision is which unanswered customer question costs staff the most time.",
  [["Choose the channel","For a busy switchboard, compare phone routing and after-hours coverage. For shoppers who hesitate to call, evaluate the standalone website widget and agree on the publication steps with the existing provider."],
   ["Identify the available context","Check whether an approved inventory source provides the stock number, price and status. For phone calls, agree on what the caller can say to identify the unit. For chat, test an existing listing on a phone."],
   ["Prove the handoff","Send a request from the existing customer entry point. Have the receiving salesperson locate the car, callback information and question before expanding to more pages or departments."]],
  [["Does the standalone widget navigate our vendor’s pages?","On an existing third-party site, shoppers control navigation. The hosted AutoDealership.SI showroom has the guided vehicle navigation experience."],
   ["Can we use our existing business number?","Discuss forwarding or the appropriate provider arrangement in onboarding. Test where calls land, caller experience and after-hours routing with the dealership."]],
  "Bring your current website and phone map","Choose a frequently visited vehicle page and one busy department. We can walk through the small set of changes each option requires.");

add("resources/release-notes","Changes you can check on an actual stock number",
  "A release matters when a dealership employee can tell what changed for a shopper and what changed behind the counter. Use these checks when training a new employee or reviewing a showroom update.",
  [["Inventory distribution","Open a complete vehicle and compare its public price and photo with its feed record. Set a test unit to sold and check the regenerated feed. Review exclusions for vehicles missing required merchandising fields."],
   ["Visits and follow-up","Open a scheduled test drive, reschedule it and view the outcome in the private workspace. Use a separate inquiry to try assignment, a follow-up deadline, a staff note and completion."],
   ["Local store and creative settings","Review department hours and phones on a public page, then compare the published clock with available test-drive times. Inspect a homepage banner after a creative or theme change."]],
  [["Are manufacturer program announcements included here?","OEM programs have their own status pages and are Coming Soon. An internal tool release and a manufacturer enrollment decision are tracked separately."],
   ["Where should staff report a regression?","Use the team contact page. Include the dealership subdomain, public page or private tab, stock number and the steps that produced the issue."]],
  "Try one change before your sales meeting","Pick the release most relevant to the store this week. Ask a salesperson to repeat the check in the appropriate demo or authorized workspace.");

add("resources/walkthroughs","Choose a walkthrough that answers a buying question",
  "The recorded demo helps a team see the public experience at its own pace. A live walkthrough is more useful when the used-car manager, receptionist or sales lead brings a particular problem they want to see handled.",
  [["For the inventory manager","Bring a VIN, actual mileage and a photo sequence. Review the decoded fields, the expected blanks and how the car’s stock number follows the listing into a shopper question."],
   ["For the sales desk","Start with a buyer interested in one car and a Saturday visit. Try voice or a form, confirm the request, then have another employee open the booking and explain the buyer’s stated preferences."],
   ["For the owner","Compare the hosted showroom with a phone-only or chat-only rollout. Identify what the selected plan includes, who manages the data and which third parties have to participate."]],
  [["Can we watch a recording before scheduling?","Yes. The homepage has a sales walkthrough video and a link to the public showroom so your team can try the browsing experience."],
   ["Can the discussion use our own inventory?","Bring a public listing, a stock number and any sample data you are authorized to share. A live session can evaluate the fields and actions your team needs."]],
  "Plan a ten-minute rehearsal","Write down one question each from inventory, sales and the owner. Use the recording first, then book a session around the questions that still need a live demonstration.");

add("resources/field-notes","Practical checks for running the digital lot",
  "These guides are written for the person who has to make a correction before the next shopper calls. Use a live listing and a real staff role when applying one at your dealership.",
  [["Before a vehicle goes live","Inspect its identity, equipment, photos and pricing in the same order a shopper sees them. An attractive gallery and a missing stock number still leave the phone receptionist guessing."],
   ["After a shopper books","Find the booking confirmation and compare the stock number, contact details and chosen time. If the shopper changes the appointment, update the same visit and review how your team counts it."],
   ["During the weekly check","Pick a recently sold unit, an upcoming appointment and a lead that needs a response. Check the corresponding public listing or private record, and give one employee ownership of any repair."]],
  [["Which guide should a new salesperson read first?","Start with the vehicle page checklist, then submit a sample inquiry and find the stock number in the staff handoff."],
   ["Which guide helps a manager review appointment totals?","Use Measuring test drives to define bookings, reschedules, cancellations and shown visits before comparing two weeks of performance."]],
  "Use the guides in a shift handoff","Let one person publish a sample listing and another receive its question. Record which fields made the handoff easier and which required a second call.");

add("resources/vehicle-page-checklist","Walk around the listing like you would the vehicle",
  "Use this checklist on one full vehicle page before uploading the rest of an inventory batch. Start with what identifies the unit, move through what sets it apart, then test how a shopper reaches the store.",
  [["Confirm identity and condition","Read the VIN and stock number from the listing and match them to store records. Check the year, make, model, trim and mileage. Use a source tied to the exact unit to confirm a disputed package or feature."],
   ["Arrange photos with intent","Start with an exterior view of the correct car. Include cabin, rear seat, cargo and detail views that answer the questions people ask on the phone. Review every image at mobile size and remove duplicates or images from another unit."],
   ["Test price and contact","Compare the displayed cash price, payment mode and any financed schedule with the dealer-approved figures. Submit a sample question with a stock number and confirm the receiving employee can locate the vehicle and question."]],
  [["What should we do if the VIN decoder leaves the trim blank?","Confirm it with the vehicle documentation or physical equipment. Leave unverified optional equipment out of published claims until a staff member can establish it."],
   ["What should we recheck after a vehicle sells?","Check its public shopping status and regenerated feed, then review any outstanding test drives or inquiries that may need a staff follow-up."]],
  "Tell two near-identical units apart","Show a colleague two near-identical listings and ask about an option present on only one. Their ability to name the right unit reveals how clear your merchandising is.");

add("resources/measuring-test-drives","Keep one appointment identity from booking through attendance",
  "A form opening is evidence of interest. A booking has a confirmation, a vehicle and a scheduled time. Keep those stages separate so your sales meeting can focus on why visits happened or fell through.",
  [["Build a small reconciliation sheet","For a sample week, list unique confirmations, original booking dates, current scheduled times and recorded outcomes. A rescheduled appointment keeps its identity while the time changes."],
   ["Use the correct window","Compare bookings to qualified inquiries received in a defined period. For attendance, use visits that were due in the period. Mark future and unresolved appointments separately until staff can record their outcomes."],
   ["Investigate the exceptions","Look for duplicate receipts, cancellations, a vehicle removed before the visit and visits with missing outcomes. Ask the assigned salesperson to resolve the actual event before drawing conclusions about a campaign."]],
  [["How should we treat a shopper who reloads the confirmation page?","Reconcile against the booking identity and count a confirmed visit once. A browser reload can create another page view."],
   ["Can we attribute a retail sale from a vehicle changing to sold?","Match the deal to the shopper and the appropriate sales system before reporting revenue attribution. A sold vehicle alone identifies inventory movement."]],
  "Reconcile a sample week","Bring anonymized totals for inquiries, confirmed appointments, cancellations and shown visits. Identify where your current report mixes events or uses different date windows.");

add("resources/dealer-sign-in","Start with the dealership where you work",
  "Your dealership website and the platform administration area serve different jobs. Inventory, shopper inquiries and scheduled test drives belong in the private dashboard for the specific rooftop that invited you.",
  [["Find the right sign-in","Use the exact subdomain provided in the store’s welcome link, or open Dealer sign-in in that showroom’s footer. On the sign-in screen, use the work email the store administrator invited."],
   ["Check which store opened","Confirm the dealership name before editing a vehicle. A group employee may have access to more than one store, and the stock number or shopper name alone may match a record elsewhere."],
   ["Recover an invitation","If access is missing after sign-in, ask the dealership administrator to check the invited address, organization and membership. Include the subdomain and time of the attempt when contacting support."]],
  [["Why does my billing account open a different screen?","The billing account manages subscriptions. Dealer staff access inventory and leads through their showroom’s private dealer dashboard."],
   ["Where do owners and engineers manage client sites?","Use the platform administrator or engineer sign-in links on this page. These workspaces use the permissions assigned to your platform identity."]],
  "Confirm a new employee’s access","Have the employee open the showroom footer themselves, sign in and identify the dealership name and the inventory or inquiry tab they need.");

add("company/our-approach","Follow one car all the way to the salesperson",
  "Start with a question a salesperson can answer only by looking at the car. Does the third row fold flat? Is the advertised cash down for this stock number? Can the shopper see it Saturday? Those questions reveal whether the website, voice assistant and private workspace agree.",
  [["Write down the dealership’s version of the truth","We begin with one vehicle, its VIN and stock number, the approved price and the pictures the store can publish. The used-car manager identifies what can be read from the VIN, what requires a sticker and what needs a walk out to the lot. That distinction guides what the assistant can tell a shopper."],
   ["Watch the handoff from both sides","A shopper opens that listing on a phone, asks a question and requests a test drive. A second person plays the salesperson and opens the private record. We compare the exact car, callback details, appointment receipt and any trade or seating note. If the salesperson has to ask the shopper to start over, the handoff needs more work."],
   ["Change something that matters","Move the appointment, sell the vehicle or change Saturday’s opening time. Recheck the places the original fact appeared, including the listing, booking flow and feed. That exercise makes it clear which system owns each change and which outside provider controls the timing."],
   ["Give the store a launch decision it can make","An independent lot might be ready once a single salesperson can publish a car and answer its lead. A franchise rooftop may also need manufacturer sign-off or CRM delivery evidence. We identify those dependencies, put a name against each and agree on what the dealer will verify before switching domains."]],
  [["What happens if our current website already works well?","Start with the problem that brought you here. A phone receptionist or standalone chat widget may be enough. During discovery we identify the existing provider, available inventory context and the person who will receive the handoff."],
   ["What if the shopper asks something the AI cannot verify?","The useful next step is a staff question linked to the car. The salesperson can inspect the vehicle or its documentation and respond with a specific answer."],
   ["How do you decide that a feature is ready for our store?","A named dealership employee should be able to repeat the shopper task and find its result. Outside requirements such as official manufacturer approval or an authorized DMS feed carry their own acceptance evidence."]],
  "Bring the question you answered twice last week","Bring one public vehicle listing and the words a shopper actually used. We’ll use that example to show what the shopper sees, what the assistant can verify and what the employee needs at the other end.");

add("company/about","A showroom built around the dealership’s working day",
  "AutoDealership.SI brings a dealership’s inventory website, assisted shopping and private sales workspace together. Its starting point is the everyday gap between a shopper looking at a particular vehicle and the employee who picks up the conversation.",
  [["A place to publish the vehicle","The store maintains photos, stock numbers, equipment and pricing for its own lot. Different dealership setups can emphasize cash, conventional estimates or published Buy Here Pay Here schedules."],
   ["A way to ask about that car","A shopper can browse on a phone, open the vehicle details and use a form or the hosted concierge. The stock number gives both sides a shared reference."],
   ["A place for staff to act","The dealership’s private dashboard brings inquiries and scheduled test drives to its team. Additional phone, chat and advertising options can be discussed according to the channels the store wants to operate."]],
  [["Which dealerships can explore the showroom?","Independent, Buy Here Pay Here and franchise operators can review the experience. Manufacturer website certification is Coming Soon and has separate program requirements."],
   ["Who owns the details of a listing?","Dealership staff review decoded information, set the price and decide which photos and vehicle claims to publish."]],
  "Meet us in the showroom","Choose a vehicle in the demo and bring one question about the car or the lead workflow. A live session can show both the public page and the receiving staff view.");

add("company/leadership","Bring a dealership workflow to the conversation",
  "Benjamin Boyce owns AutoDealership.SI. A conversation with the team can start with a very specific dealership problem, from a phone call losing its stock number to a shopper booking a visit that staff cannot locate.",
  [["Explain what happens today","Identify who enters inventory, who answers the first question and where a salesperson looks for the next appointment. A simple description from the people doing the work is more useful than a list of software names."],
   ["Choose a decision for the meeting","An owner might be comparing a website migration with a widget installation. A sales manager might want to inspect the actual lead handoff. Agreeing on the choice helps the team prepare the right demonstration."],
   ["Identify the external owners","Bring the names or roles of the people who control DNS, approved artwork, the existing phone line and any CRM or DMS connection. These are often separate decisions with separate timelines."]],
  [["Can an owner and a salesperson join the same session?","Yes. Their perspectives help test both the business decision and the day-to-day task the dealership will ask staff to perform."],
   ["What information should we use during a demo?","A public listing, a sample stock number and non-sensitive example contact details are enough to discuss the path from shopper to sales desk."]],
  "Set an agenda with the owner","Choose one outcome you want to verify at the end of the call. It could be a confirmed visit, a correctly routed call or a private preview your team can evaluate.");

add("company/dealer-stories","What a useful dealer story should tell you",
  "Customer stories are in preparation. A useful story should identify a real dealership workflow, show what changed for staff and explain how the dealership counted the outcome. Those details matter when another store is deciding whether an experience applies to its own lot.",
  [["Establish the starting point","Describe the type of dealership, the channel and the problem. An unanswered after-hours phone request and a mislabeled website inquiry require different fixes and should be measured separately."],
   ["Trace one concrete example","Follow an authorized sample through the listing, shopper contact and staff action. Keep private customer details out of the public account and let the dealership review anything attributed to its employees."],
   ["Explain the measurement","Identify the period, the numerator and the source of any result. Bookings, visits shown and verified retail sales belong to different stages and tell different stories."]],
  [["Are published customer outcomes available here now?","The customer-story collection is planned. The live showroom and recorded walkthrough are available for evaluating the product experience today."],
   ["Can my dealership propose a story?","Use the team meeting calendar to discuss the workflow, evidence and permissions your dealership is comfortable sharing."]],
  "Recreate the journey for yourself","Try the public showroom with an example stock number. Ask the team to demonstrate the receiving side so you can judge the handoff directly.");

add("company/work-with-us","Show us the dealership problem you know firsthand",
  "Useful contributions can come from people who have answered dealership phones, maintained an inventory feed, reviewed franchise artwork or trained salespeople. The best introduction explains a specific problem and how you knew your work solved it.",
  [["For technical contributors","Bring a schema, test case or public work sample showing how you preserved a vehicle, rooftop or event identity. Explain how the system handled a retry, stale record or failed handoff."],
   ["For implementation specialists","Describe a launch involving store staff and an outside provider. Which person controlled DNS, phone routing or access? What did you verify with the dealership before calling it live?"],
   ["For dealer operators","Choose one task a new employee often gets wrong. Show how the current process works and what information must survive when the next employee takes over."]],
  [["Is this a listing for a specific open role?","This page invites introductions. The team can discuss its current needs, role scope and any formal hiring process directly."],
   ["May I share a private dealership database as a sample?","Use an anonymized example, diagram or public work sample. Keep shopper identities, credentials and dealership-confidential records out of an introduction."]],
  "Bring one working example","Book an introduction with a short description of the person you helped, the action they took and how you verified the result.");

add("partners/integrations","Start an integration conversation with the record that must arrive",
  "An integration request becomes testable when the dealership can name the record, its owner and its destination. A vehicle feed, a customer inquiry, an appointment, an email reply and a sold outcome each carry different permissions and identifiers.",
  [["Check the existing connection","The platform uses NHTSA vPIC for available VIN data, Clerk for staff identity, ElevenLabs for voice plans and Whop for subscriptions. Dealer-owned Resend teams can grant email access through OAuth. Each connection has its own purpose and activation steps."],
   ["Specify a dealer system request","Give the exact CRM or DMS name, dealer code, provider contact and direction of transfer. Ask which party is authorized to send a lead or read inventory. Supply a sample record with customer information removed."],
   ["Review changes and failures","Decide what should happen to a changed stock number, a duplicate inquiry and a sold vehicle. The receiving system should identify the same location and event after a retry. Verify delivery using the recipient’s actual acknowledgment."]],
  [["Does being listed here imply that every dealer can activate a CRM or DMS?","Availability depends on the provider, product, permissions and a tested connection for the rooftop. Ask about your exact vendor and workflow during discovery."],
   ["Who controls our email provider relationship?","With dealer-owned Resend OAuth, the dealership selects the team and controls its provider relationship. Confirm the sending domain and authorized workflows for the specific store."]],
  "Bring one redacted example","Choose a lead or inventory record from the two systems you want to connect. Identify which fields must arrive, what proves delivery and who handles exceptions.");

add("partners/standards","Make every dealership handoff possible to verify",
  "A successful API response is only one part of a connection. The dealership should be able to open the receiving system, find the correct unit or inquiry and understand who is responsible when the transfer fails.",
  [["Identify access and ownership","Record the authorizing dealership, location, systems, permitted fields and support contacts. Keep provider credentials and shopper details out of public tickets and sample records."],
   ["Agree on each event","Specify the source identifier and what creation, update, withdrawal or sale means. A vehicle disappearing from a partial file and a confirmed sale can demand very different actions."],
   ["Rehearse recovery","Test a valid event, a rejection, a timeout and a replay. Compare the producer’s receipt with the receiver’s record, document the resolution and repeat the case after either side changes its interface."]],
  [["Can a dealer group authorize all locations with one sample?","Confirm which rooftops the agreement covers and check a second location for isolation. Retain the provider’s actual scope and support contact."],
   ["When is a pilot ready to expand?","Agree on measurable acceptance conditions before starting. A functioning retry path, matching record totals and a named person handling exceptions are useful evidence."]],
  "Bring a failure case","Choose the last lead or vehicle update that needed manual repair. Walk us through where it stalled and what would have let the receiving team recover it.");

add("contact","Bring the decision your dealership needs to make",
  "Use the meeting calendar for a sales conversation, an implementation review or help identifying the correct workflow. A short description of the store, the customer entry point and the result you expect will make the session more useful.",
  [["For a new showroom","Bring the current website address and a public listing you know well. Name the employee who publishes the car, the person who answers the inquiry and the first action the demo should prove."],
   ["For phone or chat","Bring the main call flow or a website page where customers ask repeated questions. Identify the line, department or inbox that should receive the handoff and its business hours."],
   ["For a current store","Bring the dealership subdomain, stock number or appointment reference, approximate time and a description of what appeared on screen. Use example contact information when demonstrating a private workflow."]],
  [["Can we look at the platform before booking a meeting?","The homepage includes the recorded sales walkthrough, a link to the live showroom and the monthly and annual plan selector."],
   ["Do we need to switch domains to see our setup?","An engineer can prepare a dealership preview on its own subdomain. Custom domain and DNS work can follow once the store agrees on a launch plan."]],
  "Pick an outcome for the session","Decide whether you want to see a published vehicle, a received inquiry, a confirmed appointment or a routed call. Invite the person who will use that outcome every day.");

add("products","Choose a tool by the job your staff needs to finish",
  "A dealership might need a better way to merchandise incoming trades, answer phone questions or convert web interest into actual visits. Start with one concrete outcome, then compare the products that touch it.",
  [["Publish the vehicle","Lotline Showroom handles the customer-facing listing. Rooftop Profile supplies the store facts around it. Feed Desk checks which eligible units can enter the Google vehicle export."],
   ["Handle the conversation","Lot Guide supports voice-assisted shopping on the hosted showroom. Front Desk Voice addresses the inbound phone line. Lot Chat is the standalone option for a dealership keeping its existing website."],
   ["Give staff a measurable outcome","Stock Inbox gives staff the customer’s question and vehicle reference. Visit Count ties appointment reporting to confirmed bookings. Planned products for search visibility, permissions and editorial review have their own status labels."]],
  [["Are these product names separate subscription plans?","The names describe capabilities. The pricing page lists the commercial plans, included voice time and available add-ons. Confirm the features in the plan you choose."],
   ["How do we evaluate the combination we need?","Bring the same car through each step. Ask the team to show how a published listing becomes a question, who receives it and how a booked visit is recorded."]],
  "Choose a car and a staff owner","A vehicle page is a good place to begin, but finish the demonstration on the screen the receiving employee will actually open.");

add("solutions","Build the rollout around how the store sells",
  "An independent lot, a Buy Here Pay Here operation and a franchise dealership may sell a similar vehicle with very different pricing, approval and follow-up processes. Use the solution that resembles your operating model to plan a first demonstration.",
  [["For owner-operated lots","Start with a VIN, a few actual photos and an inquiry the owner or salesperson can answer. Check whether staff can publish the car and work the lead between other responsibilities."],
   ["For in-house financing","Bring a dealer-approved payout schedule. Review cash pricing, down payment, term and payment frequency against the shopper’s view before introducing additional communication channels."],
   ["For groups and franchises","Identify the owner of each rooftop’s data, assets and access. Ask which manufacturer or vendor approvals apply. A private preview gives reviewers a place to compare the experience before a public change."]],
  [["Can our store start with voice and keep the current website?","Yes. Evaluate the phone receptionist or standalone chat widget and agree on the receiving team before enabling a new channel."],
   ["How should we pick a pilot rooftop?","Choose one with a staff owner who knows the inventory, can test a shopper handoff and has access to the required domain or provider contacts."]],
  "Define a first-day success","Choose one task the dealership should be able to perform on day one. Review the public result and the private record together.");

add("resources","Put the walkthrough beside your actual dealership process",
  "Use the recorded demo to see the shopper experience, the field guides to test it with your staff and the release notes to decide which workflow to revisit after an update.",
  [["See the public experience","Watch the recorded demonstration, then open the showroom and choose a stock number. Try the vehicle page, the shopping filters and a question tied to the selected car."],
   ["Review the staff outcome","The test-drive guide explains what to count after a shopper books. The vehicle page checklist covers identity, equipment, photos, price and the contact path your team publishes."],
   ["Return after a change","Use the release notes to repeat one affected task. For example, when department hours change, check the published information and the appointment options separately."]],
  [["Which resource is best before a sales call?","The walkthrough gives a broad picture. Bring one specific question or current listing to a live session if a particular staff workflow needs verification."],
   ["Where do staff sign in?","The Dealer sign-in resource opens the dashboard on the store’s own subdomain. Your dealership administrator controls invitations for its team."]],
  "Make a training exercise","Pair a new salesperson with an inventory manager. Give one the vehicle checklist and the other a shopper question, then meet at the inquiry record.");

add("company","Meet the people and decisions behind the showroom",
  "This platform starts with dealership-owned inventory and the conversation that follows it. The company pages explain how the team evaluates a workflow, what it asks of a pilot store and how to discuss working together.",
  [["How the team evaluates a feature","The approach begins with one stock number and one shopper task. Dealer staff should be able to trace the same facts from the public page through the private outcome."],
   ["How leadership gets involved","Bring an owner-level choice to a walkthrough, such as whether to migrate the site, add phone coverage or start with a private preview. Identify which employees can validate that choice."],
   ["How evidence is presented","Customer stories are in preparation. Current evaluation can use the live showroom, a recorded walkthrough and a guided staff-side demonstration with sample information."]],
  [["Can an implementation partner or industry specialist reach the team?","Yes. Use Work with us or the partner standards page to shape an introduction around a concrete operational or integration problem."],
   ["What should a dealer group discuss first?","Identify the first location, the person who can authorize its data and the specific workflow that will decide whether to expand."]],
  "Meet around one stock number","Bring a vehicle your team knows well. A useful first conversation can start with its publication details and end with how a salesperson would handle a visit.");

add("partners","Decide which side owns the change",
  "A dealer rarely replaces every system in one rollout. Useful integrations preserve a location, an event identity and a way to prove the receiving system has acted on the right record.",
  [["Map the customer path","Identify where the shopper starts, the fields that must transfer and the employee who will use the result. An inventory publication and a CRM appointment require different evidence."],
   ["Confirm vendor permission","Ask the dealership and provider for the applicable access, terms, fields and test environment. A working connection for one product or rooftop cannot establish the scope for another."],
   ["Make operations part of the test","A pilot should cover a successful record and a failure. Name the employee or vendor who can correct misleading data, retry safely and verify that old information has left the destination."]],
  [["Where can we see the existing platform connections?","The Integration directory lists the foundation services used today and the details needed to evaluate a proposed dealer system connection."],
   ["How do vendors begin a technical conversation?","Come with a redacted sample, the authorized use case, receiving system and the result that proves the integration works."]],
  "Draw the event on one page","Start with a dealership, a stock number and an event. Identify the system that creates it, the system that consumes it and the evidence each retains.");

add("oem","Prepare a brand review before discussing enrollment",
  "OEM programs are Coming Soon. A franchise-style storefront, dealer-owned artwork and an internal approval are useful pieces of a review. Final provider eligibility belongs to the manufacturer’s current program for the dealership, market and service involved.",
  [["Select the specific make","Review the brand’s own program or identity references when they are public. Write down which materials require access through the dealer and who can request them for this rooftop."],
   ["Build a review packet","Collect the current retailer lockup, approved imagery, disclosure, offer dates and region. Preview the actual mobile and desktop placements and keep the reviewed artwork with its source and revision."],
   ["Obtain the program decision","Ask the program contact to confirm website eligibility, any separate advertising requirements and the process for written approval. Keep that response and its effective dates with the dealership’s rollout plan."]],
  [["Can a dealership enroll in an AutoDealership.SI OEM website program today?","OEM certification is a future milestone. Current discussions can cover templates, internal review and the evidence required to approach a specific manufacturer."],
   ["Can my staff store manufacturer reference material privately?","The private dealer workspace includes a manufacturer reference library and supports dealer-supplied artwork with its source and usage notes. Review current rights before publishing any logo or creative."]],
  "Start with one promotion","Bring the manufacturer name, dealer program contact and one piece of artwork your store is authorized to use. Compare the proposed page with the actual requirements.");

add("ads-management","Choose a campaign around the shopper’s next decision",
  "Campaign Studio gives a dealership a way to review the creative, offer and destination together. A shopper exploring options needs a different ad from one ready to ask about a specific stock number.",
  [["Start with an audience problem","A trade-in shopper wants to understand what their current vehicle might contribute. A BHPH shopper may be deciding whether the down payment and cadence fit. Choose the problem, the store’s actual offer and the next useful page."],
   ["Verify the advertised inventory","Check availability, photos, stock number, price and the mobile destination before approving the creative. An ad about one car should take the shopper to that car while available."],
   ["Separate cost and outcome","The management fee and dealer-funded media budget are separate. Identify the agreed market, channels, spend and conversion event before a campaign goes live. The examples on the sales page illustrate creative concepts."]],
  [["Are the sample social ads real dealership campaigns?","They are examples of campaign formats and buying stages. A real launch requires dealer-approved creative, inventory, account access and budget."],
   ["Can we advertise in-house financing?","Start with a dealership that offers the terms, verify the actual vehicle and payment details, and have the appropriate reviewer approve the offer and channel before launch."]],
  "Choose two ads for the same vehicle","Try one aimed at a shopper discovering a problem and one for a shopper ready to book. Compare their landing pages and the staff action each should generate.");

add("home","See the same vehicle from both sides of the showroom",
  "A vehicle page, an incoming call and a private sales record are often three separate experiences. AutoDealership.SI lets a dealership evaluate how those pieces come together around a specific stock number.",
  [["Start on the public website","Filter the inventory, open a vehicle and inspect its gallery, features and price. Ask a question using the words a shopper would actually use."],
   ["Move to the dealership","Use a guided session to see the inquiry or booked visit from the staff side. Check the stock number, callback details and notes the salesperson will need."],
   ["Choose the commercial setup","Compare monthly and annual website packages, optional phone coverage and the widget options for an existing site. Bring expected voice usage into the plan discussion."]],
  [["Can our dealership see a preview before launch?","An assigned engineer can prepare the dealership’s website on a subdomain. The store can review its pages and inventory before connecting a custom domain."],
   ["Where do we start if we only want chat?","Open the pricing section and review the packages for keeping your existing website. A meeting can clarify the inventory source and staff handoff."]],
  "Book a shopper-to-staff walkthrough","Bring one stock number, one shopper question and the person who would handle the lead. Use them throughout the demonstration.");

// Each scenario poses a dealer discovery question. It does not assert a manufacturer requirement.
const brandScenarios = {
  "acura":["Separate the retailer identity from the model campaign","An Acura retailer may have a model launch banner and an all-makes pre-owned row on the same site. Identify the approved retailer lockup and sales destination for each before choosing a header or applying the creative across pages.","Which version of the Acura retailer name belongs in the mobile masthead?","Ask the retailer’s program contact for the approved file and naming convention for this physical location. Preview it beside the dealer contact actions at a narrow width.","A new-model inquiry and a pre-owned inquiry","Use one of each to confirm where the shopper lands and which Acura sales team receives the question."],
  "alfa-romeo":["Plan the Alfa Romeo presence in a shared showroom","A group may merchandise Alfa Romeo alongside a sister franchise. Identify which entry pages, inventory rows and dealer phone numbers belong to the Alfa Romeo operation before accepting a masthead design.","Can shared group artwork be used on the Alfa Romeo landing page?","Request the brand-specific asset, the intended market and approval for that placement. Review the group identity and the retailer lockup as separate elements.","A shopper entering through the Alfa Romeo page","Follow a stock-specific inquiry and check the group name, selected marque and receiving sales destination at each step."],
  "bmw":["Keep vehicle configuration attached to the specific BMW","Two cars with the same model badge can have different upholstery, packages or driver-assistance equipment. Use a sample pair to test what the retailer can prove on the listing and what must return to a salesperson.","Which materials support a package or option claim?","Ask the BMW retailer for vehicle-specific evidence, the approved description and any current program requirements for using photography or badges. Keep the evidence with the reviewed vehicle.","Two similarly named BMW listings","Ask about one optional feature by stock number and have the receiving employee locate the supporting document."],
  "buick":["Give Buick inventory its own route through a dual-brand store","When a Buick and GMC store shares an address, the correct department phone may be the same while the offer, logo and featured inventory are different. Review the Buick shopper’s route without relying on a group homepage.","Which Buick details should stay distinct at a shared address?","Have the retailer identify the Buick lockup, eligible inventory set, offer disclosure and receiving team. Confirm the division’s current rules with the program contact.","A Buick promotion at a dual-brand rooftop","Open the banner on a phone and verify that every destination, vehicle and disclosure belongs to the Buick offer."],
  "cadillac":["Review a Cadillac appointment as well as the page that books it","For a retailer arranging a vehicle presentation, the promise on the landing page should match the staff and unit available for the appointment. Use the review to connect the creative, current inventory and receiving advisor.","How should an inquiry for a reserved vehicle be handled?","Agree with the Cadillac retailer on the availability wording and the person who can confirm an alternative. Check that public language and the staff handoff give the shopper the same expectation.","A reserved unit and a sales appointment","Trace the inquiry, read the availability language and ask the advisor what they can confirm before inviting the shopper in."],
  "chevrolet":["Separate commercial and retail Chevrolet inquiries","A store serving fleet operators and personal buyers may need two very different conversations from a single truck listing. Decide which details can be verified from the unit and which employee should receive the request.","Where should a shopper asking about a specific upfit be sent?","Use the Chevrolet dealer’s actual equipment documentation and designated contact. Review the description, stock number and route to the employee who can verify the installation.","A truck with dealer-installed equipment","Compare the base vehicle facts, actual upfit and destination of a shopper’s question before releasing the listing."],
  "chrysler":["Prepare a Chrysler people-mover listing around verified seating","A family asking how a seat folds needs an answer for the particular vehicle. Match cabin photos, equipment and family-oriented promotional creative to the stock number in the offer.","Can the sales team distinguish advertised seating from this unit’s configuration?","Use actual interior photos and documentation for the featured Chrysler. Have a salesperson inspect anything the listing cannot establish before confirming a family visit.","A shopper asking to try their child seats","Carry the selected stock number and the request for a seating demonstration into a test-drive note."],
  "dodge":["Keep performance language attached to the advertised Dodge","A buyer may ask about a package or motor specification after seeing striking campaign artwork. Ground the reply in vehicle-specific data and check that the artwork actually applies to the featured listing.","How should an unverified performance claim be reviewed?","Bring the factory or dealer-approved material for the Dodge unit and the program’s permitted copy. Route conflicting figures to a reviewer before publishing them in a headline or a voice response.","A feature claim from a performance campaign","Open the promoted Dodge, compare the claim with the documented equipment and send one unanswered question to a salesperson."],
  "ferrari":["Review photography permission one asset at a time","A Ferrari press photograph, a dealer’s original image and a customer’s consignment photo can have different publication permissions. Label the source and intended page before selecting a homepage or vehicle-gallery image.","Can an image found in the Ferrari Media Centre go straight on the dealer website?","Ask the retailer to obtain authorization for the commercial placement. Keep the supplied file, permitted use and reviewer with the asset selected for the site.","An appointment to view a specific vehicle","Review the dealer’s own gallery and route the viewing request to the employee who can confirm access to that unit."],
  "fiat":["Make the FIAT buyer’s actual question easy to route","For a buyer comparing a city car’s size, equipment or charging arrangement, the details of the unit matter. Decide which FIAT listings and supporting information belong on a shared retailer site.","Who should verify a shopper’s question about included accessories?","Ask the FIAT retailer to inspect the actual unit and supplied equipment. Treat an accessory pictured in campaign material as a claim to confirm against the unit.","A compact-car inquiry with an accessory question","Open the FIAT listing on a phone, inspect the photos and verify the receiving salesperson can identify the exact question."],
  "ford":["Distinguish Ford truck availability from capability","A buyer asking whether a particular truck can do a job needs more than a model name. Start with the cab, bed, powertrain and vehicle-specific supporting documentation before discussing capability.","How should a towing or payload question reach the sales team?","Keep the Ford stock number and the buyer’s intended use in the inquiry. Have an authorized employee verify the individual vehicle’s rating and equipment before making a commitment.","A truck buyer with a trailer question","Follow the exact unit from the listing to an employee who has the documentation needed to answer."],
  "genesis":["Coordinate a Genesis showroom visit with the actual retailer","A curated presentation depends on the right vehicle, appointment location and employee being ready. Check the retailer’s approved identity and the handoff to the person who can prepare that vehicle.","Where should the customer meet the retailer for a requested appointment?","Confirm the Genesis rooftop, customer entrance, current hours and staff destination. Use the resulting store information when reviewing the public contact and confirmation experience.","A first visit to a Genesis retailer","Ask a shopper unfamiliar with the location to find the entrance, request a time and tell the sales advisor which vehicle they selected."],
  "gmc":["Identify the GMC truck behind a trim-level comparison","A shopper comparing GMC trucks may be looking at similar names with different bed lengths, equipment or cab configurations. The listing, creative and question should all identify the exact unit.","Which truck attributes should a salesperson verify before confirming availability?","Start with the GMC stock number, actual mileage, cab and bed configuration, available package evidence and the current sales status. For specialized ratings, confirm manufacturer documentation for the unit.","Two GMC trucks from the same model year","Ask about one configuration and confirm that the sales desk can recover the correct truck without asking the shopper to restart."],
  "honda":["Check Honda new, used and certified destinations separately","A Honda retailer’s inventory pages may lead to materially different shopping expectations. Review the inventory condition, source of any certified designation and program-approved retailer artwork for each destination.","Who can authorize a certified label on a Honda unit?","Ask the dealership’s program owner to confirm the individual vehicle’s status and approved wording. A filter or badge should follow that record when the unit changes status.","A certified-stock shopper’s question","Open the exact unit, verify its condition wording and route a question about certification to the appropriate Honda employee."],
  "hyundai":["Tie Hyundai promotional artwork to its source and region","A dealer may receive a campaign asset through an authorized portal and a similarly styled image through another channel. Record which supplied file, dates and geography the retailer is entitled to publish.","What should accompany an image supplied from Hyundai Ad Planner?","Request the current asset, its intended use, market, offer terms and review contact from the dealership’s authorized user. Verify the mobile crop and the associated landing page.","A regional Hyundai campaign that ends on a specific day","Compare the approved file with the scheduled banner and check what the buyer sees when the period closes."],
  "infiniti":["Inspect the INFINITI navigation at a phone width","Fine spacing, a wordmark and a retailer name can change dramatically in a narrow header. Review the current digital guide with the person responsible for the US retailer program, then preview the actual menu and sales action together.","Which mobile header version should the retailer approve?","Request the permitted symbol or wordmark treatment, background and placement from the INFINITI program contact. Inspect the final header next to the dealership contact link.","A mobile menu over the public inventory","Open the menu with touch and keyboard, check the selected identity treatment and follow one vehicle inquiry to the retailer."],
  "jeep":["Separate factory packages from dealer-installed equipment on a Jeep","A buyer asking about an off-road feature, roof or towing accessory may be looking at a dealer-installed item. Use stock-specific photos and supporting documents so the feature description fits the unit.","How should a salesperson answer a capability question that the listing cannot establish?","Capture the Jeep stock number and intended use in the inquiry. Have the dealership verify the configuration before making a claim or publishing it in a promotion.","A shopper asking about equipment from a Jeep photo","Compare the factory and dealer-supplied evidence, then verify the question reaches the employee who can inspect the vehicle."],
  "kia":["Align a Kia trim comparison with the available cars","Similar listings can have different seating layouts, equipment or delivery status. Keep the trim and stock number visible when a shopper moves from a search result to the full page.","What happens if the Kia shown in a campaign is still in transit?","Agree on the dealership’s approved availability language and contact destination. Review the inventory page and any appointment promise together before promoting the vehicle.","An in-transit Kia alongside an on-lot unit","Ask to see each vehicle and check whether the public language and staff handoff establish different expectations."],
  "lexus":["Review which Lexus experience the retailer is promising","A shopper requesting a presentation, a trade conversation or a service appointment should reach the employee responsible for that experience. Define the receiving department and hours before reviewing each page.","Which agreements should a Lexus retailer check before switching its website?","Use the dealership’s authorized Lexus Digital Solutions contact and program terms to confirm enrollment, permitted data uses and the effective date of any provider change.","A sales appointment and a service request","Follow each path from a Lexus page and check that the correct location and department are visible at the handoff."],
  "lincoln":["Give a Lincoln shopper a retailer-specific handoff","A Lincoln retailer may share systems with a neighboring Ford operation. Check the identity, phone routing and appointment destination a Lincoln shopper actually sees before approving any group-wide site settings.","Can a group carry over the Ford header to the Lincoln rooftop?","Have the retailer request the current Lincoln-specific artwork and permitted treatment through its program contact. Review the page against the Lincoln materials for the location.","A Lincoln visitor entering through a group website","Open the retailer page from a phone, ask about one Lincoln stock number and verify who receives the appointment."],
  "maserati":["Keep Maserati gallery provenance with each featured vehicle","An individual vehicle’s condition, options and photography can be especially important to a buyer arranging a viewing. Review the dealer’s own listing evidence alongside the current authorized brand material.","What should the retailer request in addition to a trademark reference?","Obtain the current Maserati retail website specification, dealer-specific identity file and permission for the intended campaign assets through the authorized dealer contact.","A shopper arranging a vehicle viewing","Compare the photos and option description on one Maserati stock number with the note the sales contact receives."],
  "mazda":["Resolve the Mazda identity revision before approving the header","A saved website guide and a newer brand announcement may refer to different revision dates. The dealership needs the current US retail instruction and authorized file before deciding which mark to place on a live site.","Does a newer brand announcement automatically replace the dealer’s approved web artwork?","Ask the Mazda program contact which revision applies to the dealership, market and rollout date. Keep that direction with the exact image used in the preview.","A mobile header before and after an artwork change","Use the current dealer-provided file, document the revision and compare the preview with the version approved for that Mazda location."],
  "mercedes-benz":["Set the Mercedes-Benz offer and viewing location together","A retailer with distinct sales, service or pre-owned facilities needs clear addresses at the point of inquiry. Review the stock location, brand artwork and destination of the shopper’s request as a single path.","Which Mercedes-Benz document authorizes the intended retail design?","Request the current dealer-specific identity package and written publication terms from the retailer. A public legal notice helps identify the rights owner; the program contact can confirm the exact permitted use.","A pre-owned unit located at another facility","Ask for a viewing, inspect the location shown to the shopper and verify the employee can arrange access to the actual unit."],
  "mini":["Show the MINI actually configured for the buyer","Roof color, upholstery and equipment are details a shopper may remember more readily than a trim name. Order the actual gallery and match the description to the specific MINI before publishing it in a promotion.","Should a MINI retailer reuse a related brand’s digital program materials?","Request the current MINI retailer pack and the program’s artwork and approval contact. Record the correct source for each asset used in the private site preview.","Two MINI listings with visually different equipment","Ask about one roof or interior treatment and verify the staff member can identify the exact car from the inquiry."],
  "mitsubishi":["Make one Mitsubishi retailer’s launch requirements explicit","A public dealer-development contact is a starting point for finding the right program staff. Establish which regional website requirements and retailer assets apply before proposing a migration timetable.","What should we ask the manufacturer before planning a Mitsubishi DNS cutover?","Ask who owns US dealer website eligibility, whether the proposed provider can be used and which current artwork and offer rules apply to the rooftop. Obtain the decision with a date.","A Mitsubishi website replacement review","Bring the existing inventory, service and contact URLs and identify each decision the retailer must have in writing before a switchover."],
  "nissan":["Check what a Nissan dealer expects from an inventory handoff","Review one newly arrived Nissan, one vehicle still awaiting photos and one sold unit. The group should agree on which records appear publicly and how a salesperson verifies a shopper’s question about each.","Can a public description of Nissan website benefits establish provider eligibility?","Use the public program page to identify the right questions. Ask the Nissan dealership’s program administrator to confirm the actual vendor, rooftop, service scope and approval date.","A Nissan that sells after a shopper requests a visit","Review how the listing and feed change and how staff locate the original request to offer an alternative."],
  "porsche":["Review the Porsche wordmark and the specific car separately","A digital design-system example helps identify the intended treatment of a mark. A retailer’s use on a live US website also needs the current retail program’s direction and permission for the exact creative.","Which details should a Porsche retailer check before featuring a configured vehicle?","Match the listing to the individual stock number, option evidence and actual gallery. Ask the program owner which wordmark treatment and image rights apply to the placement.","A configured Porsche with a disputed option","Prepare a private listing, compare the wording against the supporting documents and have the designated reviewer approve the version."],
  "ram":["Keep commercial Ram configurations identifiable through the inquiry","A work-truck shopper can ask about a chassis or upfit that looks similar to another unit online. Record stock identity, actual configuration and the employee who can confirm the details before arranging a viewing.","How should an inquiry about an upfit or capacity be reviewed?","A Ram salesperson or commercial specialist should verify the particular vehicle’s documentation, including any dealer or third-party equipment, before confirming the buyer’s use case.","A commercial truck with a specific equipment request","Follow the inquiry from the advertised Ram stock number to the specialist who can check its configuration."],
  "subaru":["Connect a Subaru shopper’s lifestyle question to actual equipment","A prospective buyer may ask whether a carrier, hitch or accessory shown with the model is fitted to the particular unit. A staff note tied to the stock number helps an employee inspect the vehicle before the shopper travels.","What should be checked before publishing a locally sponsored creative?","Ask the Subaru retailer for the authorized identity treatment, any relevant licensing permission, the intended local placement and the campaign dates. Store the approved file and source together.","An accessory question and a weekend appointment","Ask about the actual Subaru equipment and confirm the receiving employee can prepare the unit and answer the question."],
  "toyota":["Choose the Toyota retailer logo treatment deliberately","Toyota’s public dealership identity examples distinguish dealer typeset and co-brand treatments. Review the store’s existing logo in that context, then ask the retailer which approved file and current program instructions apply to this website.","Which Toyota logo belongs beside our dealership name?","Use the retailer’s approved treatment and check spacing, contrast and the actual mobile placement against the applicable dealer materials. A general brand example alone cannot authorize the store’s specific use.","A Toyota dealer identity on both background colors","Preview the authorized light and dark assets on a phone and desktop next to the dealership name and contact action."],
  "volkswagen":["Match Volkswagen identity references to the US dealer program","A global brand resource and a US retailer enrollment process answer different questions. Use both in discovery to identify the correct artwork, applicable dealership program and contact who can approve the use.","Where should a Volkswagen dealer confirm whether a provider can go live?","Ask the US dealer digital program contact for the rooftop’s eligibility, market, applicable services and the current review process. Keep the confirmation with the preview’s approved revision.","A Volkswagen campaign from brand asset to retailer inquiry","Check the source file, destination, dealership identity and receiving employee before discussing a launch date."]
};

const productWorkstations = {
  lotline:["Where the inventory manager works","Open Inventory in the dealer dashboard, add or edit the vehicle, enter its VIN and stock number, and arrange the vehicle photo gallery. Save the listing and open the shopper’s full vehicle page. Compare the first photo, stock number and pricing mode on the two screens."],
  "local-reach":["Where a store corrects a public fact","In Website settings, open Branding & store settings for department phones, published hours and the dealership address. Use Website pages for the related shopper destination. Save the change and check both the visible contact details and the link a search visitor would follow."],
  "answer-index":["What a proposed pilot would record","The marketing lead would record the exact question, market, date, answer surface, cited URL and relevant dealership fact in a repeatable review. These are proposed report fields. Today, use the public dealership or vehicle page as the evidence in a manual sample."],
  "deal-path":["Where finance staff review the terms","Use Branding & store settings to set the dealership’s financing mode. From Inventory, open the car, select its payment options and enter the applicable pricing. For BHPH, compare the saved schedule with the one management approved before opening the buyer-facing listing."],
  "offer-board":["Where the image and approval meet","An authorized employee selects Homepage banners under Website settings to manage a slide. The franchise reviewer uses OEM programs to review the program revision and exact artwork. After publication, open the homepage and follow the banner all the way to its destination."],
  "shopper-paths":["What the pilot owner would configure","The proposed merchandising workspace would record the trigger, inventory filter, fallback page and staff owner for each path. For a manual demonstration today, use an existing inventory filter, inspect its results and decide where a no-match shopper should go."],
  "rooftop-profile":["Where the store manager edits a location","Under Website settings, open Branding & store settings. Use Published department hours, Department phones and Dealership address. Save the profile and open the public contact destination for that rooftop to check the result."],
  "stock-inbox":["Where the receiving employee works","Open Shopper inquiries in the dealer dashboard. Search for the stock number, read the shopper’s question and open the inquiry to set its owner and follow-up. Today surfaces due work, and Scheduled test drives contains visits that have actually been booked."],
  "visit-count":["Where staff close out a visit","Open Scheduled test drives, find the confirmation, and review the vehicle and time before rescheduling or recording attendance. If staff correct a previously recorded attendance outcome, include the correction note. Use the same confirmation when reconciling the conversion event."],
  "contact-permissions":["What the proposed cross-channel record contains","A designated store administrator would review the sender, shopper contact, channel, declared purpose, source, capture time and any later withdrawal. The intended record would let the employee responsible for follow-up explain why a particular contact was eligible or suppressed."],
  "access-review":["What an accessibility reviewer would deliver","For each reproducible issue, the proposed review would identify the exact route and task, keyboard or touch action, expected result, observed result and retest outcome. A correction to a vehicle form should be retested on the actual form in the dealer’s selected theme."],
  "lot-guide":["Where to verify the conversation’s outcome","On the public listing, open the concierge and identify the vehicle. In the private dashboard, check Shopper inquiries for a submitted question or Scheduled test drives for a confirmed booking. Website voice usage is a separate tab for reviewing website voice consumption."],
  "front-desk":["What the onboarding team should document","For each inbound number, write down the department, hours, destination number, after-hours behavior and employee authorized to change the route. Run an actual call against the agreed setup and check the receiving phone before promoting the new experience."],
  "lot-chat":["What the website manager should test","Place the widget through the existing site provider’s installation process. On a sample listing, submit a question containing the stock number and example callback details. Confirm the team can retrieve those details from the agreed lead destination for that installation."],
  "copy-desk":["What an editor would approve","The proposed editorial record would hold the source vehicle or offer, draft, field-level questions, reviewer and final revision. Use an existing published listing and its source material to demonstrate the proposed review process before committing a draft to the site."],
  "feed-desk":["Where to correct an excluded vehicle","Open Marketing in the dealer dashboard and inspect the Google vehicle feed diagnostics. Search for the affected unit, correct its fields in Inventory and revisit the feed. The store code is under Branding & store settings, in Google vehicle feed."]
};
for (const [id,[title,text]] of Object.entries(productWorkstations)) {
  pages.get("products/"+id).sections.unshift({title,text});
}

