const library = JSON.parse(readFileSync(new URL("../../showroom/brand-library/catalog.json",import.meta.url),"utf8"));
for (const brand of library.brands) {
  const [headline,intro,question,answer,demoTitle,demoText] = brandScenarios[brand.id];
  const source = library.sources[brand.sources[0]];
  const route = "oem/"+brand.id;
  add(route,headline,intro,[
    ["Start with the retailer’s evidence",brand.note],
    ["Evidence to bring to the review",reviewEvidence[brand.id]],
    ["Record the scope of approval","OEM programs are Coming Soon. Ask the "+brand.name+" program owner which rooftop, market, dates and services a future approval would cover. Retain the decision separately from the dealer’s internal creative review."]
  ],[[question,answer],["Can our "+brand.name+" store enroll with AutoDealership.SI as a certified website provider today?","Certification is a future milestone. The available next step is a private product and requirements review with the dealership and its program contact."]],
    demoTitle,demoText);
  pages.get(route).sections[0].source = {label:source.title,url:source.url};
}

export function editorialFor(page) {
  const raw = typeof page === "string" ? page : (page?.key ?? page?.path);
  if (typeof raw !== "string") throw new TypeError("A page key or path is required");
  const key = raw.replace(/^\/+|\/+$/g,"") || "home";
  const entry = pages.get(key);
  if (!entry) throw new Error("Missing sales editorial for "+key);
  return entry;
}
